const std = @import("std");
const mem = std.mem;
const math = std.math;
const Allocator = mem.Allocator;
const types = @import("../core/types.zig");
const Tensor = @import("../core/tensor.zig").Tensor;
const stableHash = @import("../core/io.zig").stableHash;
const Error = types.Error;

pub const SSI = struct {
    root: ?*Node,
    allocator: Allocator,
    height: usize = 0,
    size: usize = 0,
    max_height: usize = 6,

    const Node = struct {
        hash: u64,
        children: ?[*]?*Node,
        segment: ?Segment,
        collision_chain: ?*CollisionNode,
        height: usize,
        is_leaf: bool,
        children_count: usize,

        pub fn init(allocator: Allocator, hash: u64, height: usize) !Node {
            _ = allocator;
            return .{
                .hash = hash,
                .children = null,
                .segment = null,
                .collision_chain = null,
                .height = height,
                .is_leaf = height == 0,
                .children_count = if (height > 0) (@as(usize, 1) << @as(u6, @intCast(@min(height, 6)))) else 0,
            };
        }

        pub fn deinit(self: *Node, allocator: Allocator) void {
            if (self.children) |ch| {
                allocator.free(ch[0..self.children_count]);
            }
            if (self.segment) |*seg| seg.deinit(allocator);
            var chain = self.collision_chain;
            while (chain) |c| {
                const next = c.next;
                c.seg.deinit(allocator);
                allocator.destroy(c);
                chain = next;
            }
        }
    };

    const CollisionNode = struct {
        seg: Segment,
        next: ?*CollisionNode,
    };

    const Segment = struct {
        tokens: []u32,
        position: u64,
        score: f32,
        anchor_hash: u64,

        pub fn init(allocator: Allocator, tokens: []u32, pos: u64, score: f32, anchor: u64) !Segment {
            return .{ .tokens = try allocator.dupe(u32, tokens), .position = pos, .score = score, .anchor_hash = anchor };
        }

        pub fn deinit(self: *Segment, allocator: Allocator) void {
            allocator.free(self.tokens);
        }

        pub fn hash(self: *const Segment, seed: u64) u64 {
            var hasher = std.hash.Wyhash.init(seed);
            hasher.update(std.mem.asBytes(&self.position));
            var i: usize = 0;
            while (i < self.tokens.len) : (i += 1) {
                hasher.update(std.mem.asBytes(&self.tokens[i]));
            }
            return hasher.final();
        }
    };

    pub fn init(allocator: Allocator) SSI {
        return .{ .root = null, .allocator = allocator, .height = 0, .size = 0, .max_height = 6 };
    }

    fn recursiveDeinit(node: *Node, allocator: Allocator) void {
        if (node.children) |ch| {
            var i: usize = 0;
            while (i < node.children_count) : (i += 1) {
                if (ch[i]) |child| {
                    recursiveDeinit(child, allocator);
                }
            }
        }
        node.deinit(allocator);
        allocator.destroy(node);
    }

    pub fn deinit(self: *SSI) void {
        if (self.root) |root| {
            recursiveDeinit(root, self.allocator);
        }
    }

    fn updateParentHash(node: *Node) void {
        if (node.is_leaf) return;
        var combined_hash: u64 = 0;
        if (node.children) |ch| {
            var i: usize = 0;
            while (i < node.children_count) : (i += 1) {
                if (ch[i]) |child| {
                    combined_hash ^= child.hash;
                }
            }
        }
        node.hash = combined_hash;
    }

    pub fn addSequence(self: *SSI, tokens: []u32, position: u64, is_anchor: bool) !void {
        const segment_hash = blk: {
            var hasher = std.hash.Wyhash.init(position);
            var i: usize = 0;
            while (i < tokens.len) : (i += 1) {
                hasher.update(std.mem.asBytes(&tokens[i]));
            }
            if (is_anchor) hasher.update(&[_]u8{1});
            break :blk hasher.final();
        };
        var current = &self.root;
        var h = @min(self.height, self.max_height);
        var parent_stack = std.ArrayList(*Node).init(self.allocator);
        defer parent_stack.deinit();

        while (h > 0 or current.* == null) {
            if (current.* == null) {
                const node = try self.allocator.create(Node);
                node.* = try Node.init(self.allocator, 0, h);
                current.* = node;
                if (h == self.height and self.height < self.max_height) self.height += 1;
            }
            if (h > 0) {
                const effective_height = @min(h, 6);
                const effective_height_u8 = @as(u8, @intCast(effective_height));
                if (current.*.?.children == null) {
                    current.*.?.height = effective_height;
                    current.*.?.is_leaf = false;
                    const child_count = @as(usize, 1) << @as(u6, @intCast(effective_height_u8));
                    current.*.?.children_count = child_count;
                    const children = try self.allocator.alloc(?*Node, child_count);
                    @memset(children, null);
                    current.*.?.children = children.ptr;
                }
                try parent_stack.append(current.*.?);
                const node_height_u6 = @as(u6, @intCast(effective_height_u8));
                const shift_amount = if (effective_height_u8 >= 64) @as(u6, 0) else @as(u6, @intCast(64 - effective_height_u8));
                const mask = ((@as(u64, 1) << node_height_u6) - 1);
                const bucket = (segment_hash >> shift_amount) & mask;
                h -= 1;
                current = &current.*.?.children.?[bucket];
            } else break;
        }
        const leaf = current.* orelse blk: {
            const node = try self.allocator.create(Node);
            node.* = try Node.init(self.allocator, segment_hash, 0);
            node.segment = try Segment.init(self.allocator, tokens, position, 0.0, if (is_anchor) segment_hash else 0);
            current.* = node;
            break :blk node;
        };
        leaf.hash = segment_hash;
        if (leaf.segment != null and leaf.segment.?.position != position) {
            const collision = try self.allocator.create(CollisionNode);
            collision.* = .{
                .seg = try Segment.init(self.allocator, tokens, position, 0.0, if (is_anchor) segment_hash else 0),
                .next = leaf.collision_chain,
            };
            leaf.collision_chain = collision;
        } else {
            if (leaf.segment) |*seg| seg.deinit(self.allocator);
            leaf.segment = try Segment.init(self.allocator, tokens, position, 0.0, if (is_anchor) segment_hash else 0);
        }

        while (parent_stack.popOrNull()) |parent| {
            updateParentHash(parent);
        }

        self.size += 1;
        try self.compact();
    }

    pub fn retrieveTopK(self: *SSI, query_tokens: []u32, k: usize, allocator: Allocator) ![]types.RankedSegment {
        var heap = std.PriorityQueue(types.RankedSegment, void, struct {
            pub fn lessThan(_: void, a: types.RankedSegment, b: types.RankedSegment) std.math.Order {
                return std.math.order(a.score, b.score);
            }
        }.lessThan).init(allocator, {});
        defer heap.deinit();
        const query_hash = blk: {
            var hasher = std.hash.Wyhash.init(0);
            var i: usize = 0;
            while (i < query_tokens.len) : (i += 1) {
                hasher.update(std.mem.asBytes(&query_tokens[i]));
            }
            break :blk hasher.final();
        };
        try self.traverse(self.root, query_hash, &heap, k);
        var top_k = try allocator.alloc(types.RankedSegment, @min(k, heap.count()));
        var i: usize = heap.count();
        while (heap.removeOrNull()) |seg| {
            if (i > 0) {
                i -= 1;
                top_k[i] = seg;
            }
        }
        return top_k;
    }

    fn traverse(self: *SSI, node: ?*Node, query_hash: u64, heap: anytype, k: usize) !void {
        if (node == null) return;
        const n = node.?;
        if (n.is_leaf) {
            if (n.segment) |seg| {
                try self.addSegmentToHeap(seg, query_hash, heap, k);
            }
            var chain = n.collision_chain;
            while (chain) |c| {
                try self.addSegmentToHeap(c.seg, query_hash, heap, k);
                chain = c.next;
            }
        } else {
            if (n.children) |ch| {
                if (n.height > 0) {
                    const node_height = @min(n.height, 6);
                    const node_height_u8 = @as(u8, @intCast(node_height));
                    const node_height_u6 = @as(u6, @intCast(node_height_u8));
                    const shift_amount = if (node_height_u8 >= 64) @as(u6, 0) else @as(u6, @intCast(64 - node_height_u8));
                    const mask = ((@as(u64, 1) << node_height_u6) - 1);
                    const bucket = (query_hash >> shift_amount) & mask;
                    if (ch[bucket]) |child| try self.traverse(child, query_hash, heap, k);
                    var i: usize = 0;
                    while (i < (@as(usize, 1) << node_height_u6)) : (i += 1) {
                        if (i == bucket) continue;
                        if (ch[i]) |child| try self.traverse(child, query_hash, heap, k);
                    }
                }
            }
        }
    }

    fn addSegmentToHeap(self: *SSI, seg: Segment, query_hash: u64, heap: anytype, k: usize) !void {
        const seg_hash = seg.hash(seg.position);
        const similarity = self.computeSimilarity(query_hash, seg_hash);
        const ranked = types.RankedSegment{
            .tokens = try self.allocator.dupe(u32, seg.tokens),
            .score = similarity,
            .position = seg.position,
            .anchor = seg.anchor_hash != 0,
        };
        if (heap.count() < k) {
            try heap.add(ranked);
        } else if (heap.peek()) |top| {
            if (similarity > top.score) {
                var removed = heap.remove();
                removed.deinit(self.allocator);
                try heap.add(ranked);
            } else {
                self.allocator.free(ranked.tokens);
            }
        }
    }

    fn computeSimilarity(self: *SSI, h1: u64, h2: u64) f32 {
        _ = self;
        const xor_val = @popCount(h1 ^ h2);
        return 1.0 - (@as(f32, @floatFromInt(xor_val)) / 64.0);
    }

    pub fn compact(self: *SSI) !void {
        if (self.size < 10000) return;
        var segments = std.ArrayList(struct { tokens: []u32, position: u64, score: f32, anchor_hash: u64 }).init(self.allocator);
        defer {
            for (segments.items) |item| {
                self.allocator.free(item.tokens);
            }
            segments.deinit();
        }
        var stack = std.ArrayList(*Node).init(self.allocator);
        defer stack.deinit();
        if (self.root) |root| try stack.append(root);
        while (stack.popOrNull()) |node| {
            if (node.is_leaf and node.segment != null) {
                const seg = node.segment.?;
                try segments.append(.{
                    .tokens = try self.allocator.dupe(u32, seg.tokens),
                    .position = seg.position,
                    .score = seg.score,
                    .anchor_hash = seg.anchor_hash,
                });
                var chain = node.collision_chain;
                while (chain) |c| {
                    try segments.append(.{
                        .tokens = try self.allocator.dupe(u32, c.seg.tokens),
                        .position = c.seg.position,
                        .score = c.seg.score,
                        .anchor_hash = c.seg.anchor_hash,
                    });
                    chain = c.next;
                }
            } else if (node.children) |ch| {
                var i: usize = 0;
                while (i < node.children_count) : (i += 1) {
                    if (ch[i]) |child| try stack.append(child);
                }
            }
        }
        if (self.root) |root| {
            recursiveDeinit(root, self.allocator);
        }
        self.root = null;
        self.height = 0;
        self.size = 0;
        for (segments.items) |item| {
            try self.addSequence(item.tokens, item.position, item.anchor_hash != 0);
        }
    }

    pub fn updateScore(self: *SSI, position: u64, new_score: f32) !void {
        var stack = std.ArrayList(*Node).init(self.allocator);
        defer stack.deinit();
        if (self.root) |root| try stack.append(root);
        while (stack.popOrNull()) |node| {
            if (node.is_leaf and node.segment != null) {
                if (node.segment.?.position == position) {
                    node.segment.?.score = new_score;
                    return;
                }
                var chain = node.collision_chain;
                while (chain) |c| {
                    if (c.seg.position == position) {
                        c.seg.score = new_score;
                        return;
                    }
                    chain = c.next;
                }
            }
            if (node.children) |ch| {
                var i: usize = 0;
                while (i < node.children_count) : (i += 1) {
                    if (ch[i]) |child| try stack.append(child);
                }
            }
        }
        return error.NotFound;
    }

    pub fn getSegment(self: *const SSI, position: u64) ?Segment {
        var stack = std.ArrayList(*const Node).init(self.allocator);
        defer stack.deinit();
        if (self.root) |root| stack.append(root) catch return null;
        while (stack.popOrNull()) |node| {
            if (node.is_leaf) {
                if (node.segment) |seg| if (seg.position == position) return seg;
                var chain = node.collision_chain;
                while (chain) |c| {
                    if (c.seg.position == position) return c.seg;
                    chain = c.next;
                }
            }
            if (node.children) |ch| {
                var i: usize = 0;
                while (i < node.children_count) : (i += 1) {
                    if (ch[i]) |child| stack.append(child) catch continue;
                }
            }
        }
        return null;
    }

    pub fn exportToTensor(self: *SSI, allocator: Allocator) !Tensor {
        const num_segments = self.size;
        const t = try Tensor.init(allocator, &.{ num_segments, 129 }, f32);
        var idx: usize = 0;
        var stack = std.ArrayList(*Node).init(allocator);
        defer stack.deinit();
        if (self.root) |root| try stack.append(root);
        const data_ptr: [*]f32 = @ptrCast(@alignCast(t.data.ptr));
        while (stack.popOrNull()) |node| {
            if (node.is_leaf and node.segment != null) {
                const seg = node.segment.?;
                var i: usize = 0;
                while (i < seg.tokens.len and i < 128) : (i += 1) {
                    data_ptr[idx * 129 + i] = @floatFromInt(seg.tokens[i]);
                }
                while (i < 128) : (i += 1) {
                    data_ptr[idx * 129 + i] = 0.0;
                }
                data_ptr[idx * 129 + 128] = @floatFromInt(seg.position);
                idx += 1;
            } else if (node.children) |ch| {
                var i: usize = 0;
                while (i < node.children_count) : (i += 1) {
                    if (ch[i]) |child| try stack.append(child);
                }
            }
        }
        return t;
    }

    pub fn importFromTensor(self: *SSI, t: *const Tensor) !void {
        if (t.shape.len != 2 or t.shape[1] != 129) return error.InvalidTensorShape;
        self.deinit();
        self.root = null;
        self.height = 0;
        self.size = 0;
        const num_segments = t.shape[0];
        const data_ptr: [*]const f32 = @ptrCast(@alignCast(t.data.ptr));
        var s: usize = 0;
        while (s < num_segments) : (s += 1) {
            var tokens: [128]u32 = undefined;
            var i: usize = 0;
            while (i < 128) : (i += 1) {
                tokens[i] = @intFromFloat(data_ptr[s * 129 + i]);
            }
            const position: u64 = @intFromFloat(data_ptr[s * 129 + 128]);
            try self.addSequence(&tokens, position, false);
        }
    }

    pub fn merge(self: *SSI, other: *const SSI) !void {
        var stack = std.ArrayList(*Node).init(self.allocator);
        defer stack.deinit();
        if (other.root) |root| try stack.append(root);
        while (stack.popOrNull()) |node| {
            if (node.is_leaf and node.segment != null) {
                const seg = node.segment.?;
                try self.addSequence(seg.tokens, seg.position, seg.anchor_hash != 0);
            } else if (node.children) |ch| {
                var i: usize = 0;
                while (i < node.children_count) : (i += 1) {
                    if (ch[i]) |child| try stack.append(child);
                }
            }
        }
    }

    pub fn split(self: *SSI, threshold: f32) !SSI {
        var new_ssi = SSI.init(self.allocator);
        var stack = std.ArrayList(*Node).init(self.allocator);
        defer stack.deinit();
        if (self.root) |root| try stack.append(root);
        while (stack.popOrNull()) |node| {
            if (node.is_leaf and node.segment != null) {
                const seg = node.segment.?;
                if (seg.score > threshold) {
                    try new_ssi.addSequence(seg.tokens, seg.position, seg.anchor_hash != 0);
                }
            } else if (node.children) |ch| {
                var i: usize = 0;
                while (i < node.children_count) : (i += 1) {
                    if (ch[i]) |child| try stack.append(child);
                }
            }
        }
        return new_ssi;
    }

    pub fn balance(self: *SSI) !void {
        if (self.size < 1024) return;
        var segments = std.ArrayList(struct { tokens: []u32, position: u64, score: f32, anchor_hash: u64 }).init(self.allocator);
        defer {
            for (segments.items) |item| {
                self.allocator.free(item.tokens);
            }
            segments.deinit();
        }
        var stack = std.ArrayList(*Node).init(self.allocator);
        defer stack.deinit();
        if (self.root) |root| try stack.append(root);
        while (stack.popOrNull()) |node| {
            if (node.is_leaf and node.segment != null) {
                const seg = node.segment.?;
                try segments.append(.{
                    .tokens = try self.allocator.dupe(u32, seg.tokens),
                    .position = seg.position,
                    .score = seg.score,
                    .anchor_hash = seg.anchor_hash,
                });
            } else if (node.children) |ch| {
                var i: usize = 0;
                while (i < node.children_count) : (i += 1) {
                    if (ch[i]) |child| try stack.append(child);
                }
            }
        }
        if (self.root) |root| {
            recursiveDeinit(root, self.allocator);
        }
        self.root = null;
        const optimal_height = @min(@as(usize, @intFromFloat(math.log2(@as(f32, @floatFromInt(self.size))))) + 1, self.max_height);
        self.height = optimal_height;
        self.size = 0;
        for (segments.items) |item| {
            try self.addSequence(item.tokens, item.position, item.anchor_hash != 0);
        }
    }

    pub fn serialize(self: *SSI, writer: anytype) !void {
        try writer.writeInt(usize, self.height, .little);
        try writer.writeInt(usize, self.size, .little);
        var node_id_map = std.AutoHashMap(*Node, usize).init(self.allocator);
        defer node_id_map.deinit();
        var next_id: usize = 1;
        var stack = std.ArrayList(*Node).init(self.allocator);
        defer stack.deinit();
        if (self.root) |root| {
            try node_id_map.put(root, next_id);
            next_id += 1;
            try stack.append(root);
        }
        while (stack.popOrNull()) |node| {
            if (node.children) |ch| {
                var i: usize = 0;
                while (i < node.children_count) : (i += 1) {
                    if (ch[i]) |child| {
                        if (!node_id_map.contains(child)) {
                            try node_id_map.put(child, next_id);
                            next_id += 1;
                            try stack.append(child);
                        }
                    }
                }
            }
        }
        try writer.writeInt(usize, node_id_map.count(), .little);
        stack.clearRetainingCapacity();
        if (self.root) |root| try stack.append(root);
        while (stack.popOrNull()) |node| {
            const node_id = node_id_map.get(node).?;
            try writer.writeInt(usize, node_id, .little);
            try writer.writeInt(u64, node.hash, .little);
            try writer.writeInt(usize, node.height, .little);
            try writer.writeInt(usize, @intFromBool(node.is_leaf), .little);
            try writer.writeInt(usize, node.children_count, .little);
            if (node.segment) |seg| {
                try writer.writeInt(usize, 1, .little);
                try writer.writeInt(u64, seg.position, .little);
                try writer.writeAll(std.mem.asBytes(&seg.score));
                try writer.writeInt(u64, seg.anchor_hash, .little);
                try writer.writeInt(usize, seg.tokens.len, .little);
                var i: usize = 0;
                while (i < seg.tokens.len) : (i += 1) {
                    try writer.writeInt(u32, seg.tokens[i], .little);
                }
            } else {
                try writer.writeInt(usize, 0, .little);
            }
            if (node.children) |ch| {
                var i: usize = 0;
                while (i < node.children_count) : (i += 1) {
                    const child_id = if (ch[i]) |c| node_id_map.get(c).? else 0;
                    try writer.writeInt(usize, child_id, .little);
                    if (ch[i]) |c| try stack.append(c);
                }
            }
        }
    }

    pub fn deserialize(allocator: Allocator, reader: anytype) !SSI {
        var ssi = SSI.init(allocator);
        const height = try reader.readInt(usize, .little);
        const size = try reader.readInt(usize, .little);
        ssi.height = height;
        ssi.size = size;
        const node_count = try reader.readInt(usize, .little);
        var nodes = std.AutoHashMap(usize, *Node).init(allocator);
        defer nodes.deinit();
        var i: usize = 0;
        while (i < node_count) : (i += 1) {
            const node_id = try reader.readInt(usize, .little);
            const hash_val = try reader.readInt(u64, .little);
            const node_height = try reader.readInt(usize, .little);
            const is_leaf_val = try reader.readInt(usize, .little);
            const children_count = try reader.readInt(usize, .little);
            const node = try allocator.create(Node);
            node.* = .{
                .hash = hash_val,
                .children = null,
                .segment = null,
                .collision_chain = null,
                .height = node_height,
                .is_leaf = is_leaf_val != 0,
                .children_count = children_count,
            };
            try nodes.put(node_id, node);
            const has_segment = try reader.readInt(usize, .little);
            if (has_segment != 0) {
                const position = try reader.readInt(u64, .little);
                var score: f32 = undefined;
                _ = try reader.readAll(std.mem.asBytes(&score));
                const anchor_hash = try reader.readInt(u64, .little);
                const token_len = try reader.readInt(usize, .little);
                const tokens = try allocator.alloc(u32, token_len);
                var j: usize = 0;
                while (j < token_len) : (j += 1) {
                    tokens[j] = try reader.readInt(u32, .little);
                }
                node.segment = .{
                    .tokens = tokens,
                    .position = position,
                    .score = score,
                    .anchor_hash = anchor_hash,
                };
            }
            if (children_count > 0) {
                const children = try allocator.alloc(?*Node, children_count);
                @memset(children, null);
                node.children = children.ptr;
                var j: usize = 0;
                while (j < children_count) : (j += 1) {
                    _ = try reader.readInt(usize, .little);
                }
            }
        }
        var it = nodes.iterator();
        while (it.next()) |entry| {
            const node = entry.value_ptr.*;
            if (node.children) |ch| {
                var stack_pos = try std.ArrayList(usize).initCapacity(allocator, node.children_count);
                defer stack_pos.deinit();
                var k: usize = 0;
                while (k < node.children_count) : (k += 1) {
                    try stack_pos.append(0);
                }
            }
        }
        if (node_count > 0) {
            ssi.root = nodes.get(1);
        }
        return ssi;
    }

    pub fn stats(self: *const SSI) struct { nodes: usize, leaves: usize, depth: usize } {
        var nodes: usize = 0;
        var leaves: usize = 0;
        var depth: usize = 0;
        var stack = std.ArrayList(struct { node: *const Node, d: usize }).init(self.allocator);
        defer stack.deinit();
        if (self.root) |root| {
            stack.append(.{ .node = root, .d = 0 }) catch {
                return .{ .nodes = nodes, .leaves = leaves, .depth = depth };
            };
        }
        while (stack.popOrNull()) |entry| {
            nodes += 1;
            if (entry.node.is_leaf) leaves += 1;
            if (entry.d > depth) depth = entry.d;
            if (entry.node.children) |ch| {
                var i: usize = 0;
                while (i < entry.node.children_count) : (i += 1) {
                    if (ch[i]) |child| {
                        stack.append(.{ .node = child, .d = entry.d + 1 }) catch {
                            continue;
                        };
                    }
                }
            }
        }
        return .{ .nodes = nodes, .leaves = leaves, .depth = depth };
    }

    pub fn validate(self: *SSI) bool {
        var valid = true;
        var stack = std.ArrayList(*Node).init(self.allocator);
        defer stack.deinit();
        if (self.root) |root| {
            stack.append(root) catch return false;
        }
        while (stack.popOrNull()) |node| {
            if (node.is_leaf) {
                if (node.segment) |seg| {
                    const computed_hash = seg.hash(seg.position);
                    if (computed_hash != node.hash) valid = false;
                } else valid = false;
            } else {
                var child_hash: u64 = 0;
                if (node.children) |ch| {
                    var i: usize = 0;
                    while (i < node.children_count) : (i += 1) {
                        if (ch[i]) |child| {
                            child_hash ^= child.hash;
                            stack.append(child) catch {
                                continue;
                            };
                        }
                    }
                }
                if (child_hash != node.hash) valid = false;
            }
        }
        return valid;
    }
};

